const servers = ['SRV-001', 'SRV-002', 'SRV-003', 'SRV-004', 'SRV-005'];
const data = servers.map((srv, idx) => {
    const isThermalFail = (srv === 'SRV-003');
    return {
        server_id: srv,
        timestamp: new Date().toISOString().replace('T', ' ').substring(0, 19),
        cpu_temp_celsius: isThermalFail ? (88 + Math.floor(Math.random() * 5)) : (45 + Math.floor(Math.random() * 25)),
        fan_rpm: isThermalFail ? (5200 + Math.floor(Math.random() * 800)) : (2800 + Math.floor(Math.random() * 1200)),
        vcore_voltage: 1.20,
        power_watts: isThermalFail ? 560 : 240,
        internal_ip: '192.168.1.' + (20 + idx)
    };
});
msg.payload = data;
msg.headers = { 'Content-Type': 'application/json' };
return msg;
